jQuery(document).ready(function($) {
    function karaviAiAssistantEditorUi(key, fallback) {
        if (karaviAiAssistantEditor && karaviAiAssistantEditor.uiStrings && karaviAiAssistantEditor.uiStrings[key]) {
            return karaviAiAssistantEditor.uiStrings[key];
        }
        return fallback;
    }

    function getPostContent() {
        if (wp.data && wp.data.select('core/editor')) {
            return wp.data.select('core/editor').getEditedPostAttribute('content');
        } else {
            return $('#content').val();
        }
    }

    function getPostTitle() {
        if (wp.data && wp.data.select('core/editor')) {
            return wp.data.select('core/editor').getEditedPostAttribute('title');
        } else {
            return $('#title').val();
        }
    }

    $('#karavi-ai-assistant-generate-schema').on('click', function() {
        var $button = $(this);
        var $spinner = $button.siblings('.spinner');
        var $resultsDiv = $('#karavi-ai-assistant-meta-box-results');
        $button.prop('disabled', true);
        $spinner.addClass('is-active');
        $resultsDiv.hide();
        $.ajax({
            url: karaviAiAssistantEditor.restUrl + 'generate-schema',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantEditor.nonce);
            },
            data: {
                post_id: karaviAiAssistantEditor.postId
            }
        }).done(function(response) {
            $('#karavi-ai-assistant-schema-preview pre').text(response.schema);
            $resultsDiv.html('<p style="color:green;">' + karaviAiAssistantEditorUi('schemaGeneratedSuccess', 'Schema generated and saved successfully!') + '</p>').show();
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantEditorUi('unknownErrorOccurred', 'An unknown error occurred.');
            $resultsDiv.html('<p style="color:red;">' + karaviAiAssistantEditorUi('errorPrefix', 'Error:') + ' ' + message + '</p>').show();
        }).always(function() {
            $button.prop('disabled', false);
            $spinner.removeClass('is-active');
        });
    });

    $('#karavi-ai-assistant-suggest-links').on('click', function() {
        var $button = $(this);
        var $spinner = $button.siblings('.spinner');
        var $resultsDiv = $('#karavi-ai-assistant-meta-box-results');
        $button.prop('disabled', true);
        $spinner.addClass('is-active');
        $resultsDiv.hide();
        $.ajax({
            url: karaviAiAssistantEditor.restUrl + 'suggest-links',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantEditor.nonce);
            },
            data: {
                post_id: karaviAiAssistantEditor.postId
            }
        }).done(function(response) {
            var suggestionsHTML = '<strong>' + karaviAiAssistantEditorUi('suggestions', 'Suggestions:') + '</strong><ul style="margin-top:5px; padding-left: 15px;">';
            var lines = response.suggestions.split('\n');
            lines.forEach(function(line) {
                if (line.trim()) {
                    var parts = line.split('->');
                    if (parts.length === 2) {
                        suggestionsHTML += '<li style="margin-bottom: 5px;">"' + $.trim(parts[0]) + '" &rarr; <a href="' + $.trim(parts[1]) + '" target="_blank">' + $.trim(parts[1]) + '</a></li>';
                    } else {
                        suggestionsHTML += '<li style="margin-bottom: 5px;">' + line + '</li>';
                    }
                }
            });
            suggestionsHTML += '</ul>';
            $resultsDiv.html(suggestionsHTML).show();
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantEditorUi('unknownErrorOccurred', 'An unknown error occurred.');
            $resultsDiv.html('<p style="color:red;">' + karaviAiAssistantEditorUi('errorPrefix', 'Error:') + ' ' + message + '</p>').show();
        }).always(function() {
            $button.prop('disabled', false);
            $spinner.removeClass('is-active');
        });
    });

    $('#karavi-ai-assistant-improve-seo').on('click', function() {
        var $button = $(this);
        var $spinner = $button.siblings('.spinner');
        var $resultsDiv = $('#karavi-ai-assistant-meta-box-results');
        $button.prop('disabled', true);
        $spinner.addClass('is-active');
        $resultsDiv.hide();
        $.ajax({
            url: karaviAiAssistantEditor.restUrl + 'suggest-seo-improvements',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantEditor.nonce);
            },
            data: {
                post_id: karaviAiAssistantEditor.postId
            }
        }).done(function(response) {
            var analysisHtml = $('<div/>').text(response.analysis).html().replace(/\n/g, '<br>');
            $resultsDiv.html('<strong>' + karaviAiAssistantEditorUi('seoImprovementPlan', 'SEO Improvement Plan:') + '</strong><div style="margin-top:6px; white-space:normal;">' + analysisHtml + '</div>').show();
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantEditorUi('unknownErrorOccurred', 'An unknown error occurred.');
            $resultsDiv.html('<p style="color:red;">' + karaviAiAssistantEditorUi('errorPrefix', 'Error:') + ' ' + message + '</p>').show();
        }).always(function() {
            $button.prop('disabled', false);
            $spinner.removeClass('is-active');
        });
    });
});
